parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "action": {
      "type": "string",
      "enum": [
        "reply",
        "clarify",
        "self_serve",
        "escalate",
        "handoff"
      ],
      "description": "Use reply only for non-factual greetings, closings, or scope redirects; clarify for a focused question; self_serve for every factual FAQ-grounded answer; escalate for a form; handoff for an authorized direct human transfer."
    },
    "reply": {
      "type": "string",
      "description": "Plain-text message shown to the player. Do not use Markdown, repeat answered questions, or mention retrieval internals. Redirect unrelated questions to this game's support topics. Every factual claim, troubleshooting step, or optimization claim must be directly supported by exact current-turn FAQ evidence; do not infer effects or outcomes that are not explicit in that evidence."
    },
    "category": {
      "type": "string",
      "description": "Support category slug from this bot's published taxonomy. Use other when unclear."
    },
    "summary": {
      "type": "string",
      "description": "Internal summary for the human support agent"
    },
    "reward_source": {
      "type": "string",
      "description": "Reward source slug from this bot's published taxonomy when category is reward. Empty otherwise. Use unknown if unclear."
    },
    "collected_fields": {
      "type": "object",
      "additionalProperties": {
        "type": "string"
      },
      "description": "Explicit player-provided values for already answered form fields, keyed by the exact field names in the escalation field catalog. Use only known values and preserve relative dates such as yesterday verbatim."
    },
    "handoff_override_reason": {
      "type": "string",
      "enum": [
        "",
        "critical",
        "explicit_human_request",
        "post_form_followup"
      ],
      "description": "Reason an incomplete case may bypass the form. Empty unless one of the documented forced-handoff cases applies."
    },
    "faq_evidence_ids": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Exact document ids from Search FAQ Knowledge Base used by a self_serve reply. Empty for every other action."
    },
    "grounding_quotes": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "evidence_id": {
            "type": "string"
          },
          "quote": {
            "type": "string"
          }
        },
        "required": [
          "evidence_id",
          "quote"
        ],
        "additionalProperties": false
      },
      "description": "Direct quotes copied from current-turn FAQ documents. Every self_serve sentence must contain at least one quote. Empty for every other action."
    }
  },
  "required": [
    "action",
    "reply",
    "category",
    "summary",
    "reward_source",
    "collected_fields",
    "handoff_override_reason",
    "faq_evidence_ids",
    "grounding_quotes"
  ],
  "additionalProperties": false
}

